// MEESCROLLEN BIJ UITKLAPPEN — de pagina schuift mee met wat je net opende.
//
// Klap je onderin het scherm een kaart of groepsrij open, dan valt de nieuwe
// inhoud onder de vouw en zie je niets gebeuren. De pagina schuift daarom mee —
// maar nooit zó ver dat de KOP van wat je net opende uit beeld raakt. Bij een
// lange kaart zie je dus de bovenkant plus zoveel mogelijk inhoud; bij een
// korte kaart precies genoeg om de onderkant binnen te halen.
//
//   doel = min(kaarttop − marge onder een sticky topbar,
//              huidige scroll + (kaartonderkant − viewportonderkant))
//
// en er wordt alléén gescrold als die onderkant daadwerkelijk buiten beeld valt.
//
// Gedragsbron: `expandScrollTarget`, `stickyHeaderOffset`, `applyExpandScroll`
// en `scheduleExpandScroll` in de bevroren viewer (viewer-bevroren/assets/doc.js, blok
// "Meescrollen bij uitklappen"), plus de gebaar-poort die daar in fix-ronde 1
// van taak 9d op is gezet.
//
// DIT IS NIET HET SCROLLANKER (src/ui/lijst/scrollanker.ts). De grens tussen de
// twee is scherp, en ze horen niet door elkaar te lopen:
//
//   | | meescroll (hier) | scrollanker (lijst) |
//   | aanleiding | de lezer klapt iets open | het MODEL wordt herbouwd
//                                              (taalwissel, fasewissel) |
//   | doel       | nieuwe inhoud in beeld brengen — de pagina MOET bewegen |
//                  de lezer op zijn plek houden — de pagina moet juist
//                  STILSTAAN |
//   | maat       | één rechthoek: de zojuist geopende <details> |
//                  één ankerknoop plus zijn volgnummer, over een hele herbouw |
//   | mikpunt    | window.scrollTo (absolute doelpositie, geanimeerd) |
//                  window.scrollBy (correctie in rondes, instant); is de
//                  ankerknoop na de herbouw helemaal weg, dan één
//                  window.scrollTo(0, anker.scrollY) als terugval
//                  (scrollanker.ts r.127-128) |
//
// Ze kunnen elkaar niet in de weg zitten: het anker wordt vastgehouden bij een
// modelherbouw en losgelaten als het nieuwe model binnen is, en de open-stand
// die daarbij wordt teruggezet is per definitie GEEN lezersgebaar — de poort
// hieronder houdt het meescrollen dan tegen. Dat is precies waarvoor die poort
// er is.

/** De marge tussen de bovenkant van het venster (of van een sticky topbar) en
 *  de kop van wat er net openging. */
export const MEESCROLL_MARGE = 12;

/** Hoe lang een klik op een kopregel als "gebaar" blijft gelden. Ruim genoeg
 *  voor de toggle die er direct op volgt, kort genoeg om niet een latere,
 *  programmatische standwisseling mee te nemen. */
const OPEN_GEBAAR_MS = 500;

/** De maten waarop het doel wordt uitgerekend. `top`/`bottom` zijn
 *  viewport-relatief (getBoundingClientRect). */
export interface MeescrollMaten {
  top: number;
  bottom: number;
  scrollY?: number;
  viewportHeight?: number;
  headerOffset?: number;
  marge?: number;
}

/** Het rekenwerk apart en zuiver, zodat de unit-test hem zonder DOM kan
 *  toetsen. Retourneert de gewenste scrollY, of null als er niets te doen is. */
export function meescrollDoel({
  top, bottom, scrollY = 0, viewportHeight = 0,
  headerOffset = 0, marge = MEESCROLL_MARGE,
}: MeescrollMaten): number | null {
  if (!viewportHeight || bottom <= viewportHeight) return null;
  const wilTop = scrollY + top - headerOffset - marge;
  const wilOnder = scrollY + (bottom - viewportHeight);
  const doel = Math.max(0, Math.min(wilTop, wilOnder));
  return Math.abs(doel - scrollY) < 2 ? null : doel;
}

// --- De poort: meescrollen hoort bij het GEBAAR van de lezer -----------------
// Een <details> wisselt van stand om drie redenen, en maar één ervan is een
// leesgebaar:
//   1. de lezer klikt (of drukt Enter/spatie) op de kopregel — hij wil zien wat
//      eronder zit, en dan hoort de pagina mee te schuiven;
//   2. de RENDER bouwt een kaart open op (een deeplink, de onthouden
//      open-stand): de toggle vuurt zodra de knoop in het document hangt;
//   3. het HERSTEL na een modelherbouw of een sprong (revealInUi) zet de stand
//      programmatisch terug.
//
// GEMETEN in de bevroren viewer (vlierdam-kopie, venster 600px, document
// 10.500px): één klik op een ghost-chip halverwege de pagina vuurde vier smooth
// scrolls tegelijk af — naar de vier kaarten die de herrender open opbouwde,
// mikkend op 922, 2.490, 7.861 en 5.563 px. Dat was precies de klacht van de
// eigenaar: "bij toevoegen van elementen springt hij de hele pagina rond."
//
// Daarom onthoudt de kopregel welk uitklapbaar onderdeel zojuist bediend is
// (`kopBediening` in kopselectie.ts roept `onthoudOpenGebaar` aan), en scrolt
// een uitklap alleen mee als hij daarbij hoort.

let laatsteGebaar: { el: Element; t: number } | null = null;

/** De lezer bediende de kopregel van dit onderdeel. */
export function onthoudOpenGebaar(el: Element | null | undefined): void {
  laatsteGebaar = el ? { el, t: Date.now() } : null;
}

/** Het gebaar vergeten — voor tests en voor wie de poort expliciet dichtzet. */
export function vergeetOpenGebaar(): void {
  laatsteGebaar = null;
}

/** Hoogte van een eventuele STICKY/vaste topbar: die dekt de bovenkant van de
 *  kaart af en telt dus mee in de marge. Staat de balk gewoon in de flow, dan
 *  is de offset 0. */
function topbarOffset(): number {
  if (typeof document === 'undefined' || !document.querySelector) return 0;
  // `.app-kop` staat er sinds 14 sep 2026 bij: dat IS de sticky balk van deze
  // app (de twee andere namen komen uit de bevroren viewer en uit de tijd dat
  // deze functie vooruitliep op een balk die er nog niet was). De `position`-
  // toets hieronder blijft de scherprechter — staat de kop in de flow, dan is
  // de offset gewoon nul en meet dit niets.
  const bar = document.querySelector('.app-kop, .app-topbar, .doc-topbar');
  if (!bar || !bar.getBoundingClientRect) return 0;
  const pos = typeof getComputedStyle === 'function' ? getComputedStyle(bar).position : '';
  if (pos !== 'sticky' && pos !== 'fixed') return 0;
  const r = bar.getBoundingClientRect();
  return r.bottom > 0 ? r.bottom : 0;
}

/** Bewust een HERHALING van `magBewegen` in invulling.tsx, geen import: die
 *  module trekt het hele invulling-paneel mee voor drie regels predicaat. Zelfde
 *  precedent als `eigenRegelTelling` in plichten.tsx. */
function magBewegen(): boolean {
  return !(typeof window !== 'undefined' && typeof window.matchMedia === 'function'
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

function pasMeescrollToe(el: HTMLElement): void {
  const r = el.getBoundingClientRect();
  const doel = meescrollDoel({
    top: r.top,
    bottom: r.bottom,
    scrollY: window.scrollY || 0,
    viewportHeight: window.innerHeight || 0,
    headerOffset: topbarOffset(),
  });
  if (doel == null) return;
  // Altijd geanimeerd — een instante sprong laat de lezer zoeken waar hij is
  // gebleven. Enige uitzondering is de toegankelijkheidsnorm: wie
  // prefers-reduced-motion aan heeft staan, krijgt de sprong wél instant.
  const zacht = magBewegen();
  try {
    window.scrollTo({ top: doel, left: window.scrollX || 0, behavior: zacht ? 'smooth' : 'auto' });
  } catch {
    window.scrollTo(0, doel);
  }
}

/** De body van een kaart vult zich pas ná de toggle: `lazy` bouwt hem dan pas,
 *  en de tweefasige lading laat er eerst een skelet staan (`.card-loading`).
 *  Zolang de spinner draait of de hoogte nog groeit is de kaart niet af en zou
 *  er op een verkeerde maat gescrold worden. Wachten dus tot de hoogte twee
 *  rondes stilstaat en er geen skelet meer in staat. */
function plaatsMeescroll(el: HTMLElement): void {
  if (typeof window === 'undefined' || !window.scrollTo || !el.getBoundingClientRect) return;
  const raf = typeof requestAnimationFrame === 'function'
    ? requestAnimationFrame : (fn: FrameRequestCallback) => setTimeout(fn, 16);
  let vorige = -1;
  let pogingen = 0;
  const stap = () => {
    const hoogte = el.getBoundingClientRect().height;
    const bezig = el.querySelector && el.querySelector('.card-loading');
    if ((hoogte !== vorige || bezig) && pogingen < 60) {
      vorige = hoogte;
      pogingen += 1;
      raf(stap);
      return;
    }
    pasMeescrollToe(el);
  };
  raf(stap);
}

/** Dit onderdeel ging zojuist open. Kwam die stand van de lezer, dan schuift de
 *  pagina mee; kwam hij van de render of van een herstel, dan gebeurt er
 *  niets.
 *
 *  WAARVOOR HET GELDT: de hoofdkaarten (aanbod/overeenkomst/set/verzoek) en de
 *  groepsrijen van de dimensieweergave — dezelfde verzameling als
 *  `isExpandScrollTarget` in de bevroren viewer. Losse regelrijen niet: die zijn
 *  klein genoeg om zonder sprong te lezen. In de nieuwe app is dat geen
 *  klassecontrole meer maar de AANROEPPLEK: alleen `<Kaart>` en de niveaurij van
 *  `<Regelknoop>` roepen deze functie aan. */
export function meescrollNaUitklap(el: HTMLElement): void {
  const g = laatsteGebaar;
  if (!g || g.el !== el || Date.now() - g.t > OPEN_GEBAAR_MS) return;
  laatsteGebaar = null;
  plaatsMeescroll(el);
}
