// DE KOPREGEL: TE LEZEN, TE KOPIËREN — EN HET GEBAAR DAT ERUIT KOMT.
//
// Een <summary> klapt bij elke klik om, en dat botst met selecteren: wie een
// kaarttitel dubbelklikt of doorheen sleept om hem te kopiëren, ziet de kaart
// open- en dichtklappen in plaats van tekst geselecteerd te krijgen. De ene
// helft van de oplossing staat in de CSS (`user-select: text` op de tekstdragers
// in de kop, terwijl de kopregel eromheen onselecteerbaar blijft — anders sleept
// een klik naast de titel de halve kop mee); dit is de andere helft: de omklap
// ONDERDRUKKEN zodra er echt geselecteerd is.
//
// Waarom niet gewoon "meer dan één klik ⇒ niet omklappen"? Bij een dubbelklik is
// de EERSTE klik al langsgeweest en heeft de kaart al omgeklapt. Daarom twee
// dingen: bij het indrukken van de eerste klik de stand onthouden, en die bij de
// vervolgklik terugzetten. Een gewone klik merkt hier niets van — dan is er geen
// selectie en gaat de <details> zijn eigen gang — en de knoppen in de kopregel
// (verken, versienavigator, invulling) stoppen hun eigen klik al af voordat hij
// hier komt.
//
// Gedragsbron: `selectionWithin` en `summaryEl` in de bevroren viewer
// (viewer-bevroren/assets/doc.js r.266-310). Daar is `summaryEl()` de enige plek waar de
// weergave nog een <summary> maakt; hier is dat niet af te dwingen (Solid maakt
// zijn koppen in de componenten zelf), en daarom scant `selecteerbaar.test.ts`
// de bron: élke <summary> in src/ hoort deze bediening te dragen.
//
// TWEE GEDRAGINGEN, ÉÉN GEBAAR. De kopregel is de plek waar het gebaar van de
// lezer binnenkomt, en er leven er twee van: de selectiebescherming hier, en het
// MEESCROLLEN na het uitklappen (meescroll.ts). Het rekenwerk van dat tweede
// staat daar; hier staat alleen de melding "de lezer bediende deze kop", want de
// klik is de enige plek waar dat te weten valt. De twee blijven gescheiden: wie
// het meescrollen weghaalt, houdt een werkende selectiebescherming over en
// andersom.
import type { JSX } from 'solid-js';
import { onthoudOpenGebaar } from './meescroll.js';

/** Staat er een echte selectie, en ligt haar ankerpunt BINNEN deze knoop? */
export function selectieBinnen(knoop: Node): boolean {
  const sel = (typeof window !== 'undefined' && window.getSelection)
    ? window.getSelection() : null;
  if (!sel || !String(sel).trim()) return false;
  const anker = sel.anchorNode;
  const el = anker && anker.nodeType === 1 ? anker : (anker && anker.parentNode);
  return !!(el && knoop.contains && knoop.contains(el));
}

export interface KopBediening {
  onMouseDown: JSX.EventHandler<HTMLElement, MouseEvent>;
  onClick: JSX.EventHandler<HTMLElement, MouseEvent>;
}

/** De bediening van één kopregel, om op een <summary> te spreiden:
 *  `<summary class="…" {...kopBediening()}>`. Elke aanroep hoort bij één
 *  element — de onthouden stand van vóór de klik zit in de afsluiting. */
export function kopBediening(): KopBediening {
  let openBijIndrukken: boolean | null = null;
  return {
    onMouseDown(e) {
      const sum = e.currentTarget;
      if ((e.detail || 1) <= 1) {
        const vouw = sum.parentElement as HTMLDetailsElement | null;
        openBijIndrukken = vouw ? !!vouw.open : null;
      }
    },
    onClick(e) {
      const sum = e.currentTarget;
      if (!selectieBinnen(sum)) {
        // GEEN selectie ⇒ dit is een echte uitklap-klik. Meld hem, zodat het
        // meescrollen weet dat de standwisseling die zo volgt van de lezer komt
        // en niet van de render.
        onthoudOpenGebaar(sum.parentElement);
        return;
      }
      e.preventDefault();
      if ((e.detail || 1) > 1 && openBijIndrukken !== null && sum.parentElement) {
        (sum.parentElement as HTMLDetailsElement).open = openBijIndrukken;
      }
    },
  };
}
